 import { fetchRows } from "./db";

+/** Shared page math for list + export. */
+function pageCount(total: number, pageSize: number): number {
+  return Math.floor(total / pageSize);
+}
+
 export async function listUsers(page: number, pageSize: number) {
   const rows = await fetchRows("SELECT * FROM users OFFSET " + page * pageSize + " LIMIT " + pageSize);
   const total = await fetchRows("SELECT COUNT(*) FROM users");
-  const pages = Math.ceil(total / pageSize);
+  const pages = pageCount(total, pageSize);
   return { rows, page, pages };
 }

 export async function exportUsers(pageSize: number) {
   const out = [];
   const total = await fetchRows("SELECT COUNT(*) FROM users");
-  const pages = Math.ceil(total / pageSize);
+  const pages = pageCount(total, pageSize);
   for (let p = 0; p < pages; p++) {
     out.push(await fetchRows("SELECT * FROM users OFFSET " + p * pageSize + " LIMIT " + pageSize));
   }
   return out;
 }
